import 'package:flutter/material.dart';
import '../services/api_service.dart';

class MenteeSessionsScreen extends StatefulWidget { const MenteeSessionsScreen({super.key}); @override State<MenteeSessionsScreen> createState()=>_S(); }
class _S extends State<MenteeSessionsScreen>{bool loading=true;Map<String,dynamic> data={};@override void initState(){super.initState();load();}Future<void> load()async{try{final r=await ApiService().myMentoringSessions();if(mounted)setState((){data=r;loading=false;});}catch(e){if(mounted)setState(()=>loading=false);}}
String fmt(dynamic raw){final d=DateTime.tryParse(raw?.toString()??'')?.toLocal();if(d==null)return '—';String z(int n)=>n.toString().padLeft(2,'0');return '${z(d.day)}/${z(d.month)}/${d.year} às ${z(d.hour)}:${z(d.minute)}';}String label(String s)=>{'scheduled':'Agendada','completed':'Realizada','canceled':'Cancelada'}[s]??s;Color statusColor(String s)=>s=='completed'?Colors.green:s=='canceled'?Colors.red:Colors.orange;
@override Widget build(BuildContext c){final rows=List<dynamic>.from(data['sessions']??const []);return Scaffold(appBar:AppBar(title:const Text('Minhas mentorias')),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[if(data['next_session']!=null)Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Row(children:[Icon(Icons.event_available),SizedBox(width:8),Text('Próxima mentoria',style:TextStyle(fontWeight:FontWeight.bold))]),const SizedBox(height:8),Text(fmt(data['next_session']['scheduled_at']),style:Theme.of(c).textTheme.titleMedium),if((data['next_session']['agenda_note']??'').toString().isNotEmpty)Padding(padding:const EdgeInsets.only(top:6),child:Text('Pauta: ${data['next_session']['agenda_note']}'))]))),const SizedBox(height:10),Text('Agenda e histórico',style:Theme.of(c).textTheme.titleLarge),if(rows.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(18),child:Text('Nenhuma mentoria agendada ainda.'))),...rows.map((x){final r=Map<String,dynamic>.from(x);final st=(r['status']??'scheduled').toString();final color=statusColor(st);return Card(color:color.withOpacity(.08),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(12),side:BorderSide(color:color,width:1.5)),child:ExpansionTile(leading:Icon(st=='completed'?Icons.check_circle_outline:st=='canceled'?Icons.cancel_outlined:Icons.schedule,color:color),title:Text(fmt(r['scheduled_at'])),subtitle:Text(label(st),style:TextStyle(color:color,fontWeight:FontWeight.w600)),children:[Padding(padding:const EdgeInsets.fromLTRB(16,0,16,16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[if((r['agenda_note']??'').toString().isNotEmpty)Text('Pauta: ${r['agenda_note']}'),if(st=='completed'&&(r['summary']??'').toString().isNotEmpty)Padding(padding:const EdgeInsets.only(top:6),child:Text('Ata: ${r['summary']}')),if(st=='completed'&&(r['decisions']??'').toString().isNotEmpty)Padding(padding:const EdgeInsets.only(top:6),child:Text('Decisões: ${r['decisions']}')),if(st=='completed'&&(r['next_steps']??'').toString().isNotEmpty)Padding(padding:const EdgeInsets.only(top:6),child:Text('Próximos passos: ${r['next_steps']}'))]))]));})])));}}
